-- Issue #4423 Wave 4b batch 2: profiles and user_* tables.
-- 34 policies on 12 tables. Generated by
-- scripts/db/issue-4423-rls-initplan.mjs from production pg_policies.
--
-- Each policy keeps its roles, command and permissive/restrictive mode
-- (ALTER POLICY changes only the clauses it names). In USING / WITH CHECK
-- the only change is that each auth.*() / current_setting() call is
-- wrapped as a scalar sub-select, which Postgres evaluates once per
-- statement instead of once per row. Same value, same rows.
--
-- Locks: ALTER POLICY holds an ACCESS EXCLUSIVE lock on its table until
-- COMMIT. lock_timeout makes the file fail fast (55P03) instead of
-- queueing readers on every table it already altered behind one long
-- reader. On 55P03 re-run the file a minute later; it is idempotent.
-- Exact rollback: generated from production state at apply time; see the
-- private rollback pack (this script writes batchN.rollback.sql).

BEGIN;
SET LOCAL lock_timeout = '3s';
-- Names resolve exactly as they did when pg_policies printed them.
SET LOCAL search_path = public;

ALTER POLICY "Friends can read friend profiles" ON public."profiles"
  USING (((visibility_mode = ANY (ARRAY['public'::text, 'friends'::text])) AND (EXISTS ( SELECT 1
   FROM friends
  WHERE ((friends.status = 'accepted'::text) AND (((friends.user_id = ( SELECT auth.uid() AS uid)) AND (friends.friend_user_id = profiles.id)) OR ((friends.friend_user_id = ( SELECT auth.uid() AS uid)) AND (friends.user_id = profiles.id))))))));

ALTER POLICY "Profiles viewable except by blocked users" ON public."profiles"
  USING (((( SELECT auth.uid() AS uid) = id) OR (NOT is_blocked_by(id, ( SELECT auth.uid() AS uid)))));

ALTER POLICY "Users can insert own profile" ON public."profiles"
  WITH CHECK ((( SELECT auth.uid() AS uid) = id));

ALTER POLICY "Users can insert their own profile" ON public."profiles"
  WITH CHECK ((( SELECT auth.uid() AS uid) = id));

ALTER POLICY "Users can read own profile" ON public."profiles"
  USING ((( SELECT auth.uid() AS uid) = id));

ALTER POLICY "Users can update own profile" ON public."profiles"
  USING ((( SELECT auth.uid() AS uid) = id))
  WITH CHECK ((( SELECT auth.uid() AS uid) = id));

ALTER POLICY "Users can update their own profile" ON public."profiles"
  USING ((( SELECT auth.uid() AS uid) = id));

ALTER POLICY "Users can view their own profile" ON public."profiles"
  USING ((( SELECT auth.uid() AS uid) = id));

ALTER POLICY "Users can insert their own activity" ON public."user_activity"
  WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can view their own activity" ON public."user_activity"
  USING ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can insert their own interactions" ON public."user_interactions"
  WITH CHECK (((( SELECT auth.uid() AS uid) IS NOT NULL) AND (user_id = ( SELECT auth.uid() AS uid))));

ALTER POLICY "Users can update their own interactions" ON public."user_interactions"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can view their own interactions" ON public."user_interactions"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Service role manages levels" ON public."user_levels"
  USING ((( SELECT auth.role() AS role) = 'service_role'::text))
  WITH CHECK ((( SELECT auth.role() AS role) = 'service_role'::text));

ALTER POLICY "Users can insert their own location history" ON public."user_location_history"
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can view their own location history" ON public."user_location_history"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users manage own map settings" ON public."user_map_settings"
  USING ((( SELECT auth.uid() AS uid) = user_id))
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users and paired users can view preferences" ON public."user_preference_learning"
  USING (((( SELECT auth.uid() AS uid) = user_id) OR (EXISTS ( SELECT 1
   FROM pairings
  WHERE (((pairings.user_a_id = ( SELECT auth.uid() AS uid)) AND (pairings.user_b_id = user_preference_learning.user_id)) OR ((pairings.user_b_id = ( SELECT auth.uid() AS uid)) AND (pairings.user_a_id = user_preference_learning.user_id)))))));

ALTER POLICY "Users can insert their own preferences" ON public."user_preference_learning"
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can update their own preferences" ON public."user_preference_learning"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can view their own preferences" ON public."user_preference_learning"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can delete their own push tokens" ON public."user_push_tokens"
  USING ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can insert their own push tokens" ON public."user_push_tokens"
  WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can update their own push tokens" ON public."user_push_tokens"
  USING ((user_id = ( SELECT auth.uid() AS uid)))
  WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can view their own push tokens" ON public."user_push_tokens"
  USING ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can create reports" ON public."user_reports"
  WITH CHECK ((( SELECT auth.uid() AS uid) = reporter_id));

ALTER POLICY "Users can view their own reports" ON public."user_reports"
  USING ((( SELECT auth.uid() AS uid) = reporter_id));

ALTER POLICY "Users can insert their own sessions" ON public."user_sessions"
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can update their own sessions" ON public."user_sessions"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can view their own sessions" ON public."user_sessions"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Service role manages taste matches" ON public."user_taste_matches"
  USING ((( SELECT auth.role() AS role) = 'service_role'::text));

ALTER POLICY "Users read own taste matches" ON public."user_taste_matches"
  USING (((( SELECT auth.uid() AS uid) = user_a_id) OR (( SELECT auth.uid() AS uid) = user_b_id)));

ALTER POLICY "Paired users can view visits" ON public."user_visits"
  USING ((EXISTS ( SELECT 1
   FROM pairings
  WHERE (((pairings.user_a_id = ( SELECT auth.uid() AS uid)) AND (pairings.user_b_id = user_visits.user_id)) OR ((pairings.user_b_id = ( SELECT auth.uid() AS uid)) AND (pairings.user_a_id = user_visits.user_id))))));

ALTER POLICY "Users can manage their own visits" ON public."user_visits"
  USING ((( SELECT auth.uid() AS uid) = user_id))
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

COMMIT;
